import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aStr = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aStr[i]);
        }

        List<Integer> firstHalf = new ArrayList<>();
        List<Integer> secondHalf = new ArrayList<>();
        int mid = n / 2;

        generateFirst(0, 0, a, mid, m, firstHalf);
        generateSecond(mid, 0, a, n, m, secondHalf);

        Set<Integer> firstHalfSet = new HashSet<>(firstHalf);
        List<Integer> uniqueFirstHalf = new ArrayList<>(firstHalfSet);
        Collections.sort(uniqueFirstHalf);

        int maxValue = 0;

        for (int val : secondHalf) {
            int idx = lowerBound(uniqueFirstHalf, m - val);
            if (idx > 0) {
                int candidate = uniqueFirstHalf.get(idx - 1) + val;
                if (candidate > maxValue) {
                    maxValue = candidate;
                }
            }
        }

        System.out.println(maxValue);
    }

    private static void generateFirst(int i, int total, int[] a, int mid, int m, List<Integer> list) {
        if (i == mid) {
            list.add(total % m);
        } else {
            generateFirst(i + 1, total + a[i], a, mid, m, list);
            generateFirst(i + 1, total, a, mid, m, list);
        }
    }

    private static void generateSecond(int i, int total, int[] a, int n, int m, List<Integer> list) {
        if (i == n) {
            list.add(total % m);
        } else {
            generateSecond(i + 1, total + a[i], a, n, m, list);
            generateSecond(i + 1, total, a, n, m, list);
        }
    }

    private static int lowerBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) < key) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}
